mapper.select:
SELECT id, name, type, provider, base_url AS "baseUrl", model_name AS "modelName", dimension, temperature, max_tokens AS "maxTokens", timeout_ms AS "timeoutMs", is_default AS "isDefault", enabled, COALESCE(extra_params, '{}'::jsonb)::text AS "extraParamsJson", created_at AS "createdAt" FROM llm_model
AND type = #{type} AND enabled = #{enabled}
ORDER BY type ASC, is_default DESC, name ASC, id ASC
